package com.lendup.reservas.domain.model;
import static org.junit.jupiter.api.Assertions.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.UUID; import org.junit.jupiter.api.Test;
class AggregatesTest { private CondicionesAcordadas terms(){return new CondicionesAcordadas(new BigDecimal("10.00"),null,"PEN","Campus","uso","entrega","devolucion","cancelacion");}
  @Test void garantiaEsOpcionalYSnapshotEsInmutable(){var terms=terms();var r=new Reserva(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),new PeriodoPrestamo(LocalDateTime.now(),LocalDateTime.now().plusDays(1)),terms,EstadoReserva.CONFIRMADA);assertNull(r.condiciones().garantiaMonetaria());assertEquals("uso",r.condiciones().uso());}
  @Test void solicitudSoloPuedeDecidirseUnaVez(){UUID borrower=UUID.randomUUID(),lender=UUID.randomUUID();var s=new Solicitud(UUID.randomUUID(),UUID.randomUUID(),borrower,lender,new PeriodoPrestamo(LocalDateTime.now(),LocalDateTime.now().plusDays(1)),terms(),EstadoSolicitud.PENDIENTE);s.aceptar(lender);assertThrows(IllegalStateException.class,()->s.aceptar(lender));}
  @Test void permisosContextualesNoSonRolesPermanentes(){UUID borrower=UUID.randomUUID(),lender=UUID.randomUUID();var s=new Solicitud(UUID.randomUUID(),UUID.randomUUID(),borrower,lender,new PeriodoPrestamo(LocalDateTime.now(),LocalDateTime.now().plusDays(1)),terms(),EstadoSolicitud.PENDIENTE);assertThrows(SecurityException.class,()->s.aceptar(borrower));}
  @Test void cancelacionDistribuidaNoLiberaHastaConfirmacion(){var r=new Reserva(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),new PeriodoPrestamo(LocalDateTime.now(),LocalDateTime.now().plusDays(1)),terms(),EstadoReserva.CONFIRMADA);r.solicitarCancelacion();assertEquals(EstadoReserva.CANCELACION_PENDIENTE,r.estado());r.confirmarCancelacion();assertEquals(EstadoReserva.CANCELADA,r.estado());}
  @Test void condicionesRechazanBlancosLongitudesEImportesIncompatibles(){assertThrows(IllegalArgumentException.class,()->new CondicionesAcordadas(BigDecimal.ONE,null,"PEN"," ","u","e","d","c"));assertThrows(IllegalArgumentException.class,()->new CondicionesAcordadas(new BigDecimal("1.001"),null,"PEN","Campus","u","e","d","c"));assertThrows(IllegalArgumentException.class,()->new CondicionesAcordadas(BigDecimal.ONE,null,"pen","Campus","u","e","d","c"));assertThrows(IllegalArgumentException.class,()->new CondicionesAcordadas(BigDecimal.ONE,null,"PEN","x".repeat(251),"u","e","d","c"));}
  @Test void condicionesNormalizanEspaciosSinPerderSnapshot(){var terms=new CondicionesAcordadas(new BigDecimal("10.00"),BigDecimal.ZERO,"PEN"," Campus "," uso "," entrega "," devolución "," cancelación ");assertEquals("Campus",terms.lugarIntercambio());assertEquals("uso",terms.uso());}
}
